package br.pucpr.hortifrutidobairro.data

import androidx.room.Entity
import androidx.room.PrimaryKey

// Entity: Room turns this data class into the "products" table.
// Each property becomes a column.
@Entity(tableName = "products")
data class Product(
    // Primary key generated by Room (id = 0 means "new product").
    @PrimaryKey(autoGenerate = true) val id: Int = 0,
    val name: String,
    val category: String,        // "Fruta", "Verdura" or "Legume"
    val price: Double,
    val unit: String,            // e.g. "kg", "un", "maço"
    val stock: Int,
    val localProducer: String,   // empty when it is not from a local producer
    val availableForDonation: Boolean
)
